function tensor_split(a, n, axis)
    sz = size(a, axis)
    chunk = cld(sz, n)
    parts = Any[]
    start = 1
    while start <= sz
        stop = min(start + chunk - 1, sz)
        idxs = ntuple(i -> Colon(), ndims(a))
        idxs = Base.setindex(idxs, start:stop, axis)
        push!(parts, a[idxs...])
        start = stop + 1
    end
    return parts
