function tensor_position_encode(seq, d)
    T = size(seq, 1)
    D = d
    pos = collect(0:T-1)
    i = collect(0:D-1)
    pos_mat = reshape(pos, T, 1)
    i_mat = reshape(i, 1, D)
    angles = pos_mat ./ (10000.0 .^ (i_mat ./ D))
    pe = zeros(T, D)
    pe[:, 1:2:end] .= sin.(angles[:, 1:2:end])
    if D >= 2
